 altri=[("Rifacimento tetto", "/rifacimento-tetto/"), ("Guida: quanto costa rifare il tetto", "/guide/quanto-costa-rifare-il-tetto/"), ("Condomini e capannoni", "/ristrutturazione-condomini-e-capannoni/"),
        ("Isolamento sottotetto", "/isolamento-sottotetto/"), ("Bonus ristrutturazione 2026", "/bonus-ristrutturazione-2026/"), ("Impresa edile: tutte le lavorazioni", "/impresa-edile/")],
